<script>
  import { onMount, tick } from 'svelte';
  import { loadContent, safeURL, validateContent, DRAFT_KEY } from '../lib/content.js';
  import { filterAthletes, isPlaceholder } from '../lib/athletes.js';
  import { googleFormEmbed } from '../lib/forms.js';
  import Photo from './components/Photo.svelte';
  import Heading from './components/Heading.svelte';
  import Results from './components/Results.svelte';
  import Sponsors from './components/Sponsors.svelte';
  import ArticleCard from './components/ArticleCard.svelte';
  import AthleteVisual from './components/AthleteVisual.svelte';
  let data = $state(null), error = $state(''), route = $state(''), id = $state(''), menu = $state(false), scrolled = $state(false);
  let discipline = $state('all'), category = $state(''), search = $state(''), rail = $state(null);
  const preview = new URLSearchParams(location.search).get('preview') === '1';
  const routeKeys = ['athlete', 'coaching', 'athletes', 'journal', 'plans', 'contact'];
  const s = $derived(data?.site), u = $derived(data?.ui);
  const athlete = $derived(data?.athletes.find(a => a.id === id && !isPlaceholder(a)));
  const article = $derived(data?.articles.find(a => a.id === id && a.published));
  const published = $derived(data?.articles.filter(a => a.published) || []);
  const filteredNotes = $derived(published.filter(a => (!category || a.category === category) && `${a.title} ${a.excerpt} ${a.category}`.toLowerCase().includes(search.toLowerCase())));
  const title = $derived(s ? (route ? `${u.navigation[route] || s.name} | ${s.name}` : s.metaTitle) : 'Sindrino Matthews');
  async function navigate() {
    const parts = location.hash.replace(/^#\/?/, '').split('/'); route = parts[0] || ''; id = decodeURIComponent(parts[1] || '').split('?')[0];
    menu = false; discipline = 'all'; category = ''; search = '';
    await tick(); window.scrollTo({ top: 0, behavior: 'instant' });
    document.getElementById('main')?.focus({preventScroll:true});
  }
  onMount(() => {
    navigate(); loadContent({draft:preview}).then(d => data = d).catch(e => error = e.message);
    const scroll = () => scrolled = scrollY > 35;
    const refreshDraft = event => {if(preview && event.key === DRAFT_KEY && event.newValue){try{const next=JSON.parse(event.newValue);if(!validateContent(next).length)data=next;}catch{ /* Keep the last valid preview. */ }}};
    window.addEventListener('hashchange', navigate); window.addEventListener('scroll', scroll, {passive:true});
    window.addEventListener('storage',refreshDraft);
    return () => {window.removeEventListener('hashchange', navigate); window.removeEventListener('scroll', scroll);window.removeEventListener('storage',refreshDraft);};
  });
  function moveRail(direction) { rail?.scrollBy({left:direction * (rail.firstElementChild?.getBoundingClientRect().width + 24 || 320), behavior:matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth'}); }
</script>

<svelte:head><title>{title}</title>{#if s}<meta name="description" content={s.metaDescription}/>{/if}</svelte:head>
<svelte:window onkeydown={e => {if(e.key === 'Escape') menu = false;}}/>
{#if data}
{#if preview}<div id="preview-banner">Draft preview · <a href="./admin.html">Return to editor</a></div>{/if}
<a class="skip-link" href="#main" onclick={event=>{event.preventDefault();document.getElementById('main')?.focus({preventScroll:true});document.getElementById('main')?.scrollIntoView({behavior:'instant'});}}>Skip to content</a>
<header id="site-header" class:solid={route !== '' || scrolled} class:menu-open={menu} class:preview-header={preview}>
  <a class="wordmark name-logo" href="#/" aria-label={s.name + ' home'}><span>{s.navName || s.name}</span><small>{s.tagline}</small></a>
  <button class="menu-toggle" aria-label={menu ? 'Close menu' : 'Open menu'} aria-expanded={menu} aria-controls="primary-nav" onclick={() => menu = !menu}><span></span><span></span></button>
  <nav id="primary-nav" aria-label="Main navigation">{#each routeKeys as key}<a href={'#/' + key} aria-current={route === key ? 'page' : undefined} onclick={() => menu = false}>{u.navigation[key]}</a>{/each}<a class="nav-contact" href={safeURL(s.enquiryURL)}>{u.navigation.talk}</a></nav>
</header>
<main id="main" tabindex="-1">
{#if route === ''}
  <section class="hero"><Photo src={s.heroImage} alt={s.heroAlt} class="hero-image" eager/><div class="hero-shade"></div><div class="hero-content wrap"><p class="eyebrow">{s.heroEyebrow}</p><h1>{#each s.heroTitle.split('\n') as line, i}<span class:hero-title-accent={i > 0}>{line}</span>{/each}</h1><p class="hero-description">{s.heroDescription}</p><div class="hero-actions"><a class="button stride-button" href="#/coaching">{u.actions.stride}</a><a class="text-link" href="#/athlete">{u.actions.meet}</a></div></div><div class="hero-bottom wrap"><a class="scroll-cue" href="#explore" onclick={e => {e.preventDefault(); document.getElementById('explore')?.scrollIntoView({behavior:'smooth'});}}>{u.actions.explore}</a><span>{u.home.stamp}</span><span class="hero-location">{s.heroLocation}</span></div><a class="image-credit" href={safeURL(s.heroCreditURL)} target="_blank" rel="noopener noreferrer">{s.heroCredit}</a></section>
  <Sponsors sponsors={data.sponsors} copy={u.partners}/>
  <section class="intro wrap section" id="explore"><div class="intro-copy"><p class="eyebrow">{s.introEyebrow}</p><h2 class="line-breaks">{s.introTitle}</h2><p>{s.introText}</p><a class="under-link" href="#/athlete">{u.actions.getToKnow}</a><div class="intro-footnote">{s.tagline}</div></div><div class="intro-portrait"><Photo src={s.introImage} alt={s.introImageAlt} position={s.introImagePosition}/><span class="image-label">{u.home.portraitLabel}</span><div class="portrait-note">{u.home.portraitNote}</div></div></section>
  <section class="coaching-home"><div class="wrap coaching-home-inner"><div><p class="eyebrow">{s.homeCoachingEyebrow}</p><h2 class="line-breaks">{s.homeCoachingTitle}</h2></div><div><p>{s.homeCoachingText}</p><a class="button outline" href="#/coaching">{u.actions.approach}</a></div></div><div class="wrap three-principles">{#each data.coaching.philosophy as p}<div><h3>{p.title}</h3><p>{p.text}</p></div>{/each}</div></section>
  <section class="manifesto"><Photo src={s.manifestoImage} alt={s.manifestoImageAlt} class="manifesto-image"/><div class="wrap manifesto-content"><p class="eyebrow">{s.manifestoEyebrow}</p><h2 class="line-breaks">{s.manifestoTitle}</h2><p>{s.manifestoText}</p><a class="under-link" href="#/athletes">{u.actions.community}</a></div></section>
  <section class="journal-home section wrap"><div class="section-heading"><div><p class="eyebrow">{s.homeJournalEyebrow}</p><h2 class="line-breaks">{s.homeJournalTitle}</h2></div><a class="under-link" href="#/journal">{u.actions.allNotes}</a></div><div class="article-grid">{#each published.slice(0,3) as a}<ArticleCard article={a} read={u.journal.read}/>{/each}</div>{#if safeURL(s.substack)}<a class="under-link substack-link" href={safeURL(s.substack)} target="_blank" rel="noopener noreferrer">{s.substackLabel}</a>{/if}</section>
{:else if route === 'athlete'}
  {@const p = data.profile}
  <div class="profile-hero wrap"><div><p class="eyebrow">{p.eyebrow}</p><h1 class="line-breaks">{p.headline}</h1><p>{p.intro}</p><div class="tags">{#each p.disciplines as d}<span>{d}</span>{/each}</div><a class="under-link" href={safeURL(s.enquiryURL)}>{u.navigation.talk}</a></div><figure><Photo src={p.image} alt={p.imageAlt} eager photographer={p.photographer} photographerURL={p.photographerURL} prefix={u.results.photoPrefix}/></figure></div>
  <section class="wrap section split-copy"><div><p class="eyebrow">{u.profile.behind}</p><h2 class="line-breaks">{u.profile.storyTitle}</h2></div><div class="profile-story"><p>{p.bio}</p><div class="profile-links">{#each p.links as link}<a class="under-link" href={safeURL(link.url)} target="_blank" rel="noopener noreferrer">{link.label}</a>{/each}</div></div></section>
  <section class="wrap benchmark-section"><p class="eyebrow">{u.profile.benchmarks}</p><h2>{p.benchmarkTitle}</h2><dl class="benchmark-grid">{#each p.benchmarks as b}<div><dt>{b.label}</dt><dd>{b.time}</dd><dd class="benchmark-context">{b.note}</dd></div>{/each}</dl><p class="caption">{p.benchmarkNote}</p></section>
  <section class="results-section section wrap"><p class="eyebrow">{u.profile.moments}</p><h2>{u.profile.results}</h2><Results rows={p.achievements} copy={u.results}/>{#if safeURL(p.resultsURL)}<a class="under-link" href={safeURL(p.resultsURL)} target="_blank" rel="noopener noreferrer">{p.resultsLabel}</a>{/if}{#each p.goals as goal}<div class="goal"><span>{goal.status}</span><h3>{goal.title}</h3><p>{goal.target}</p></div>{/each}</section>
  <section class="gallery-section section"><div class="wrap section-heading"><div><p class="eyebrow">{u.profile.galleryEyebrow}</p><h2>{u.profile.galleryTitle}</h2></div></div><div class="gallery-grid wrap">{#each p.gallery as g}<figure><Photo src={g.image} alt={g.imageAlt} photographer={g.photographer} photographerURL={g.photographerURL} prefix={u.results.photoPrefix}/><figcaption><span>{g.caption}</span><small>{g.credit}</small></figcaption></figure>{/each}</div></section>
  <Sponsors sponsors={data.sponsors} copy={u.partners}/>
{:else if route === 'coaching'}
  {@const c = data.coaching}
  <div class="coaching-hero wrap"><div><p class="eyebrow">{u.coaching.eyebrow}</p><h1 class="line-breaks">{c.headline}</h1><p>{c.intro}</p></div><figure><Photo src={c.image} alt={c.imageAlt} eager position={c.imagePosition}/></figure></div>
  <section class="section wrap"><p class="eyebrow">{u.coaching.approach}</p><h2 class="line-breaks">{u.coaching.approachTitle}</h2><div class="philosophy-list">{#each c.philosophy as p}<div><h3>{p.title}</h3><p>{p.text}</p></div>{/each}</div></section>
  <section class="process section"><div class="wrap"><p class="eyebrow">{u.coaching.process}</p><h2>{u.coaching.processTitle}</h2><div class="three-principles">{#each c.steps as step}<div><h3>{step.title}</h3><p>{step.text}</p></div>{/each}</div></div></section>
  <div class="wide-image wrap coaching-group"><Photo src={c.groupImage} alt={c.groupImageAlt}/></div>
  <section class="section wrap"><div class="section-heading"><div><p class="eyebrow">{u.coaching.week}</p><h2>{u.coaching.weekTitle}</h2></div><p class="caption">{u.coaching.weekNote}</p></div><div class="week-grid">{#each c.sampleWeek as day}<div><span>{day.day}</span><h3>{day.title}</h3><p>{day.description}</p></div>{/each}</div><div class="center-action"><a class="button" href="#/plans">{u.coaching.options}</a></div></section>
{:else if route === 'athletes' && !id}
  <Heading eyebrow={u.team.eyebrow} title={data.team.headline} intro={data.team.intro}/><div class="wide-image wrap team-image"><Photo src={data.team.image} alt={data.team.imageAlt}/></div>
  <section class="section wrap athlete-section"><div class="section-heading"><div><p class="eyebrow">{u.team.label}</p><h2>{u.team.title}</h2></div><label class="filter-label">{u.team.filter}<select bind:value={discipline}><option value="all">{u.team.all}</option>{#each [...new Set(data.athletes.filter(a => !isPlaceholder(a)).map(a => a.discipline))] as d}<option value={d}>{d}</option>{/each}</select></label></div>
  <div class="athlete-rail-toolbar"><p>{u.team.swipe}</p><div class="carousel-controls"><button class="carousel-button rail-text" aria-label="Previous athlete profiles" onclick={() => moveRail(-1)}>{u.team.previous}</button><button class="carousel-button rail-text" aria-label="Next athlete profiles" onclick={() => moveRail(1)}>{u.team.next}</button></div></div>
  <div bind:this={rail} class="athlete-rail" role="region" aria-label={u.navigation.athletes}>{#each filterAthletes(data.athletes, discipline) as a}<article class="athlete-slide"><div class="athlete-card" class:placeholder-card={isPlaceholder(a)}><AthleteVisual athlete={a} copy={u.team}/><div><p class="eyebrow">{isPlaceholder(a) ? u.team.comingSoon : a.discipline}</p><h3>{a.name}</h3><p>{a.headline}</p>{#if !isPlaceholder(a)}{#if a.testimonial && a.testimonialApproved}<blockquote>{a.testimonial}</blockquote>{/if}<a class="under-link" href={'#/athletes/' + a.id}>{u.actions.runner}</a>{:else}<span class="placeholder-caption">{u.team.detailsPending}</span>{/if}</div></div></article>{/each}</div>
  {#if !data.athletes.length}<div class="quiet-state"><h3>{data.team.emptyTitle}</h3><p>{data.team.emptyText}</p></div>{/if}</section>
{:else if route === 'athletes' && athlete}
  <div class="wrap breadcrumb"><a class="under-link" href="#/athletes">{u.navigation.athletes}</a></div><div class="profile-hero athlete-detail wrap"><div><p class="eyebrow">{athlete.discipline}</p><h1>{athlete.name}</h1><h2 class="profile-subheading">{athlete.headline}</h2><p>{athlete.bio}</p>{#if safeURL(athlete.instagram)}<a class="under-link" href={safeURL(athlete.instagram)} target="_blank" rel="noopener noreferrer">{u.socials.instagram}</a>{/if}{#if athlete.testimonial && athlete.testimonialApproved}<blockquote>{athlete.testimonial}</blockquote>{/if}</div><figure class="athlete-detail-visual"><AthleteVisual athlete={athlete} copy={u.team}/></figure></div>
  <section class="section wrap">{#if athlete.benchmarks?.length}<h2>{u.team.benchmarks}</h2><dl class="benchmark-grid">{#each athlete.benchmarks as b}<div><dt>{b.label}</dt><dd>{b.time}</dd><dd class="benchmark-context">{b.note}</dd></div>{/each}</dl>{/if}<p class="eyebrow">{u.team.celebrating}</p><h2>{u.team.achievements}</h2><Results rows={athlete.achievements} copy={u.results}/></section><section class="section wrap goal-section"><p class="eyebrow">{u.team.goalsEyebrow}</p><h2>{u.team.goals}</h2>{#each athlete.goals as goal}<div class="goal"><span>{goal.status}</span><h3>{goal.title}</h3><p>{goal.target}</p></div>{:else}<p>{u.team.goalsPending}</p>{/each}</section>
{:else if route === 'journal' && !id}
  <Heading eyebrow={u.journal.eyebrow} title={data.journal.headline} intro={data.journal.intro}/>{#if safeURL(s.substack)}<div class="wrap"><a class="under-link substack-link" href={safeURL(s.substack)} target="_blank" rel="noopener noreferrer">{s.substackLabel}</a></div>{/if}
  <section class="wrap journal-list"><div class="journal-controls"><div class="filter-pills" role="group" aria-label="Filter field notes"><button class:active={!category} class="filter-pill" aria-pressed={!category} onclick={() => category = ''}>{u.journal.all}</button>{#each [...new Set(published.map(a => a.category))] as c}<button class:active={category === c} class="filter-pill" aria-pressed={category === c} onclick={() => category = c}>{c}</button>{/each}</div><label class="search-box"><span class="sr-only">{u.journal.search}</span><input type="search" placeholder={u.journal.searchPlaceholder} bind:value={search}/></label></div><div class="article-grid">{#each filteredNotes as a}<ArticleCard article={a} read={u.journal.read}/>{:else}<p class="quiet-state">{u.journal.empty}</p>{/each}</div></section>
{:else if route === 'journal' && article}
  <article><div class="wrap breadcrumb"><a class="under-link" href="#/journal">{u.actions.allNotes}</a></div><header class="article-heading wrap"><p class="eyebrow">{article.category}</p><h1>{article.title}</h1><p>{article.excerpt}</p><div class="article-meta"><span>{article.readTime} {u.journal.read}</span></div></header><div class="wide-image wrap"><Photo src={article.image} alt={article.imageAlt} eager/></div><div class="article-body">{#each article.paragraphs as paragraph}<p class="line-breaks">{paragraph}</p>{/each}<div class="article-end"><p>{u.journal.end}</p><a class="under-link" href={safeURL(s.enquiryURL)}>{u.actions.nextStep}</a></div></div></article>
{:else if route === 'plans'}
  <Heading eyebrow={u.pricing.eyebrow} title={data.pricing.headline} intro={data.pricing.intro}/>{#if data.pricing.draft}<p class="wrap proposed-pricing">{data.pricing.draftLabel}</p>{/if}
  <section class="wrap plans-grid">{#each data.plans as p}<article class="plan" class:featured={p.featured}>{#if p.featured}<div class="plan-highlight">{u.pricing.featured}</div>{/if}<div class="plan-body"><p class="eyebrow">{p.eyebrow}</p><h2>{p.name}</h2><p>{p.description}</p><div class="plan-price">{p.price}<span>{p.period}</span></div>{#if p.options?.length}<dl class="block-options">{#each p.options as option}<div><dt>{option.label}</dt><dd>{option.price}</dd></div>{/each}</dl>{/if}<ul>{#each p.features as f}<li>{f}</li>{/each}</ul><a class="button" class:light={p.featured} class:outline={!p.featured} href={safeURL(s.enquiryURL)}>{u.navigation.talk}</a></div></article>{/each}</section><p class="wrap pricing-note">{data.pricing.note}</p><section class="section faq-section wrap"><div><p class="eyebrow">{u.pricing.questions}</p><h2 class="line-breaks">{u.pricing.faqTitle}</h2></div><div class="faq-list">{#each data.faqs as f}<details><summary>{f.question}<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" aria-hidden="true"><path d="m5 7 5 5 5-5"/></svg></summary><p>{f.answer}</p></details>{/each}</div></section>
{:else if route === 'contact'}
  <Heading eyebrow={u.contact.eyebrow} title={s.contactHeadline} intro={s.contactIntro}/>
  <section class="wrap contact-paths"><article class="contact-path"><p class="eyebrow">{u.contact.generalEyebrow}</p><h2 class="line-breaks">{u.contact.generalTitle}</h2><p>{u.contact.generalText}</p>{#if s.email}<a class="contact-email" href={'mailto:' + s.email}>{s.email}</a><a class="button" href={'mailto:' + s.email}>{u.contact.emailLabel}</a>{:else if safeURL(s.instagram)}<a class="button" href={safeURL(s.instagram)} target="_blank" rel="noopener noreferrer">{u.socials.instagram}</a>{/if}</article><article class="contact-path coaching-contact"><p class="eyebrow">{u.contact.coachingEyebrow}</p><h2 class="line-breaks">{u.contact.coachingTitle}</h2><p>{u.contact.coachingText}</p><a class="button outline" href={safeURL(s.enquiryURL)}>{u.contact.coachingAction}</a></article></section>
  <section class="wrap contact-layout"><div class="contact-aside"><Photo src={s.contactImage} alt={s.contactImageAlt}/><div><h2>{u.contact.formTitle}</h2><p>{u.contact.text}</p><a class="under-link" href={safeURL(s.enquiryURL)} target="_blank" rel="noopener noreferrer">{u.contact.fallback}</a></div></div><div class="form-embed">{#if googleFormEmbed(s.enquiryURL)}<iframe src={googleFormEmbed(s.enquiryURL)} title={u.contact.embedTitle} loading="lazy" referrerpolicy="strict-origin-when-cross-origin"></iframe>{/if}<a class="under-link" href={safeURL(s.enquiryURL)} target="_blank" rel="noopener noreferrer">{u.actions.enquiry}</a></div></section>
{:else if route === 'credits'}
  <Heading eyebrow={u.credits.eyebrow} title={u.credits.headline} intro={u.credits.intro}/><section class="wrap prose section">{#each ['photo','partner','privacy','notes'] as key}<h2>{u.credits[key + 'Title']}</h2><p>{u.credits[key + 'Text']}</p>{/each}<a href={safeURL(s.heroCreditURL)} target="_blank" rel="noopener noreferrer">{s.heroCredit}</a><p><a href="./assets/photo-credits.json">{u.credits.photoIndex}</a></p></section>
{:else}
  <Heading eyebrow={u.notFound.eyebrow} title={u.notFound.headline} intro={u.notFound.intro}/><div class="section wrap"><a class="button" href="#/">{u.actions.home}</a></div>
{/if}
{#if !['contact','credits'].includes(route)}<section class="cta wrap"><p class="eyebrow">{u.cta.eyebrow}</p><div class="cta-row"><div><h2 class="line-breaks">{s.ctaTitle}</h2><p>{s.ctaText}</p></div><a class="button" href={safeURL(s.enquiryURL)}>{u.actions.conversation}</a></div></section>{/if}
</main>
<footer id="site-footer"><div class="footer-top wrap"><div><a class="footer-brand" href="#/">{s.name}</a><p class="brand-caption">{s.tagline}</p><p>{s.footerText}</p></div><div class="footer-links">{#each routeKeys as key}<a href={'#/' + key}>{u.navigation[key]}</a>{/each}</div><div class="footer-social">{#each [['Instagram',s.instagram],['Strava',s.strava],['Substack',s.substack]] as [label,url]}{#if safeURL(url)}<a class="social-link" href={safeURL(url)} target="_blank" rel="noopener noreferrer">{#if label !== 'Substack'}<span class={'social-icon social-' + label.toLowerCase()} aria-hidden="true"></span>{/if}<span>{u.socials[label.toLowerCase()]}</span></a>{/if}{/each}<a class="button light small" href={safeURL(s.enquiryURL)}>{u.actions.nextStep}</a></div></div><div class="footer-bottom wrap"><span>© {new Date().getFullYear()} {s.name}. {u.footer.copyright}</span><span><a href="./admin.html">{u.footer.studio}</a><span class="footer-sep">/</span><a href="#/credits">{u.footer.credits}</a></span></div></footer>
{:else}<div class="loading"><h1>Sindrino Matthews</h1><p role="status">{error || 'Loading…'}</p>{#if error}<a class="under-link" href="./">Reload website</a>{/if}</div>{/if}
